-- Warcraft Reborn Mystic Enchants whose bonus lived only in the tooltip: damage, healing or crit chance for named
-- spells while the target carries your aura, while you carry one (held when the cast started), per heal over
-- time / sting / curse / bleed of yours on the target, or under a health condition
-- (AscensionMysticEnchantBonus.cpp). amount 0 = the enchant aura effect's amount.
DROP TABLE IF EXISTS `coa_mystic_enchant_bonus`;
CREATE TABLE `coa_mystic_enchant_bonus` (
  `enchant_spell` INT UNSIGNED NOT NULL,
  `effect` TINYINT UNSIGNED NOT NULL COMMENT 'the enchant aura effect whose amount the bonus is',
  `rule` TINYINT UNSIGNED NOT NULL,
  `kind` VARCHAR(16) NOT NULL COMMENT 'damage, healing, healing_taken, crit',
  `spells` TEXT NOT NULL COMMENT 'every rank, space separated; empty = any spell',
  `school_mask` INT UNSIGNED NOT NULL DEFAULT 0,
  `use_mask` TINYINT UNSIGNED NOT NULL DEFAULT 0 COMMENT '1 = the effect class mask picks the spells',
  `self_aura` TEXT NOT NULL COMMENT 'the player has one of these (or had it when the cast started)',
  `target_aura` TEXT NOT NULL COMMENT 'the target has one of these from the player',
  `count_aura` TEXT NOT NULL COMMENT 'times each of these from the player on the target',
  `count_mechanic` TINYINT UNSIGNED NOT NULL DEFAULT 0 COMMENT 'times each aura of this mechanic from the player',
  `conditions` TEXT NOT NULL COMMENT 'space separated, all must hold (see the script)',
  `amount` INT NOT NULL DEFAULT 0,
  `multiplier` FLOAT NOT NULL DEFAULT 1,
  `comment` VARCHAR(255) NOT NULL DEFAULT '',
  PRIMARY KEY (`enchant_spell`, `effect`, `rule`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='Mystic Enchant conditional bonuses (AscensionMysticEnchantBonus.cpp)';

DELETE FROM `coa_mystic_enchant_bonus`;
